import { describe, expect, it, vi } from "vitest";

const validations = vi.hoisted(() => vi.fn());
const verdicts = vi.hoisted(() => vi.fn());
vi.mock("@/lib/prisma", () => ({
  prisma: { issueValidation: { groupBy: validations }, testVerdict: { groupBy: verdicts } },
}));

import { agentWorkDone, describeWorkDone } from "./agent-work";

describe("agentWorkDone", () => {
  it("counts each agent's confirmations, rejections and fix reviews over the last 30 days", async () => {
    validations.mockResolvedValue([
      { agentId: "a1", verdict: "accept", _count: { _all: 3 } },
      { agentId: "a1", verdict: "reject", _count: { _all: 1 } },
    ]);
    verdicts.mockResolvedValue([{ agentId: "a2", _count: { _all: 2 } }]);
    const now = new Date("2026-10-25T00:00:00Z");
    const done = await agentWorkDone(["a1", "a2", "a3"], now);
    expect(done.get("a1")).toEqual({ confirmed: 3, rejected: 1, reviews: 0 });
    expect(done.get("a2")).toEqual({ confirmed: 0, rejected: 0, reviews: 2 });
    expect(done.has("a3")).toBe(false);
    expect(validations).toHaveBeenCalledWith(expect.objectContaining({
      where: { agentId: { in: ["a1", "a2", "a3"] }, kind: "real", createdAt: { gte: new Date("2026-09-25T00:00:00Z") } },
    }));
    const since = new Date("2026-09-25T00:00:00Z");
    expect(verdicts).toHaveBeenCalledWith(expect.objectContaining({
      where: { agentId: { in: ["a1", "a2", "a3"] }, OR: [{ createdAt: { gte: since } }, { changedAt: { gte: since } }] },
    }));
  });

  it("reads nothing for no agents", async () => {
    validations.mockClear();
    expect((await agentWorkDone([])).size).toBe(0);
    expect(validations).not.toHaveBeenCalled();
  });
});

describe("describeWorkDone", () => {
  it("names only what was done", () => {
    expect(describeWorkDone({ confirmed: 2, rejected: 0, reviews: 1 })).toBe("2 confirmed · 1 fix reviewed");
    expect(describeWorkDone({ confirmed: 0, rejected: 1, reviews: 3 })).toBe("1 rejected · 3 fixes reviewed");
    expect(describeWorkDone({ confirmed: 0, rejected: 0, reviews: 0 })).toBeNull();
    expect(describeWorkDone(undefined)).toBeNull();
  });
});

import type { AgentStatus } from "@/lib/dashboard-overview";

// A body color per agent, picked from its name, so each one looks the same everywhere.
const BODY_COLORS = ["#3978F6", "#7C5CE0", "#0E9F8E", "#E07A2E", "#D04F7A", "#4A5BD4"];
const LIGHT: Record<AgentStatus, string> = {
  working: "#22C55E",
  waiting: "#F59E0B",
  idle: "#60A5FA",
  offline: "#94A3B8",
};

function colorFor(name: string): string {
  let hash = 0;
  for (const char of name) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
  return BODY_COLORS[hash % BODY_COLORS.length];
}

/**
 * A small robot standing for an agent: its own body color, and an antenna
 * light for its status (green working, amber waiting on you, blue standing
 * by, grey offline). A working agent's light pulses.
 */
export function AgentGraphic({ name, status, size = 40 }: { name: string; status: AgentStatus; size?: number }) {
  const body = colorFor(name);
  const light = LIGHT[status];
  return (
    <svg width={size} height={size} viewBox="0 0 40 40" aria-hidden="true" className="shrink-0">
      <rect x="1" y="1" width="38" height="38" rx="12" fill={body} opacity="0.12" />
      {/* antenna */}
      <line x1="20" y1="7" x2="20" y2="12" stroke={body} strokeWidth="2" strokeLinecap="round" />
      <circle cx="20" cy="6" r="2.6" fill={light} className={status === "working" ? "motion-safe:animate-pulse" : undefined} />
      {/* head */}
      <rect x="9" y="12" width="22" height="17" rx="6" fill={body} />
      <rect x="12.5" y="16" width="15" height="8.5" rx="4.25" fill="white" opacity="0.92" />
      <circle cx="17" cy="20.25" r="1.9" fill={body} />
      <circle cx="23" cy="20.25" r="1.9" fill={body} />
      {/* ears */}
      <rect x="6.5" y="17" width="2.5" height="6" rx="1.25" fill={body} />
      <rect x="31" y="17" width="2.5" height="6" rx="1.25" fill={body} />
      {/* body */}
      <rect x="13" y="30" width="14" height="6" rx="3" fill={body} opacity="0.75" />
    </svg>
  );
}

import type { IssueStage } from "@/lib/issue-stage";
import { ElapsedTime } from "@/components/elapsed-time";
import { WORK_READINESS_VOTE_THRESHOLD } from "@/lib/ticket-assignment";

const icon = "h-3 w-3 shrink-0";

function Svg({ children, className = icon }: { children: React.ReactNode; className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className={className}>
      {children}
    </svg>
  );
}

const CheckIcon = ({ className }: { className?: string }) => <Svg className={className}><path d="m5 12 4.5 4.5L19 7" /></Svg>;
const BotIcon = () => <Svg><rect x="4" y="8" width="16" height="12" rx="3" /><path d="M12 4v4M9 14h.01M15 14h.01" /></Svg>;
const ClockIcon = () => <Svg className="h-2.5 w-2.5 shrink-0"><circle cx="12" cy="12" r="9" /><path d="M12 7v5l3 2" /></Svg>;
const BulbIcon = () => (
  <Svg>
    <path d="M9 18h6M10 21h4M12 3a6 6 0 0 0-3.6 10.8c.6.5 1.1 1.3 1.1 2.2h5c0-.9.5-1.7 1.1-2.2A6 6 0 0 0 12 3Z" />
  </Svg>
);

/** A hammer that taps, in place of the word "working". Still under reduced motion. */
function HammeringIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className={`hammering ${icon}`}>
      <g className="hammering-head">
        <path d="m15 12-8.4 8.4a2.1 2.1 0 1 1-3-3L12 9" />
        <path d="M17.6 15 22 10.6M20.9 11.7 12.3 3.1a1 1 0 0 0-1.4 0L9.6 4.4a1 1 0 0 0 0 1.4l8.6 8.6a1 1 0 0 0 1.4 0l1.3-1.3a1 1 0 0 0 0-1.4Z" />
      </g>
    </svg>
  );
}
const BidIcon = () => <Svg><path d="m14 13-7.5 7.5a2.1 2.1 0 0 1-3-3L11 10M16 16l6-6M8 8l6-6M9 7l8 8M21 11l-8-8" /></Svg>;

export type IssueRowWork = {
  /** The person the work is for (the agent's owner), or the assignee. */
  person: string | null;
  /** When the active claim started; null when unknown. */
  since: Date | null;
};

/**
 * One line saying where an issue stands: Idea, Confirmed (bots), Ready for
 * bids, who is working on it and for how long, or Resolved / Closed.
 */
export function IssueRowStatus({
  status,
  stage,
  botConfirmations,
  votes,
  work,
}: {
  status: string;
  stage: IssueStage | undefined;
  botConfirmations: number;
  /** Upvotes so far, shown against the threshold while Confirming. */
  votes: number;
  work: IssueRowWork | null;
}) {
  if (work) {
    // Two lines: a working hammer and who, then how long.
    return (
      <span className="issue-row-status inline-flex min-w-0 flex-col items-start gap-0.5">
        <span className="inline-flex min-w-0 items-center gap-1.5">
          <span className="text-zk-ok-fg"><HammeringIcon /></span>
          <span className="max-w-[9rem] truncate text-zk-text2">{work.person ?? "Someone"}</span>
          <span className="sr-only">is working on it</span>
        </span>
        {work.since ? (
          <span className="inline-flex items-center gap-0.5 pl-5 text-[10.5px] tabular-nums text-zk-muted">
            <ClockIcon />
            <ElapsedTime since={work.since} />
          </span>
        ) : null}
      </span>
    );
  }
  if (status === "resolved" || status === "closed") {
    return (
      <span className={`issue-row-status inline-flex items-center gap-1 ${status === "resolved" ? "text-zk-ok-fg" : "text-zk-muted"}`}>
        <CheckIcon /> {status === "resolved" ? "Resolved" : "Closed"}
      </span>
    );
  }
  if (stage === "ready") {
    return (
      <span className="issue-row-status inline-flex items-center gap-1 text-zk-ok-fg">
        <BidIcon /> Ready for bids
      </span>
    );
  }
  if (stage === "confirmed") {
    // Bots confirmed it; it becomes Ready for bids at the upvote threshold.
    const shown = Math.min(votes, WORK_READINESS_VOTE_THRESHOLD);
    return (
      <span
        className="issue-row-status inline-flex items-center gap-1 text-zk-text2"
        title={`Confirmed by ${botConfirmations} ${botConfirmations === 1 ? "bot" : "bots"}; ${shown} of ${WORK_READINESS_VOTE_THRESHOLD} upvotes to be ready for bids`}
      >
        <span className="text-zk-accent"><BotIcon /></span>
        <span>
          Confirming… <span className="tabular-nums">({shown}/{WORK_READINESS_VOTE_THRESHOLD})</span>
        </span>
        <span className="sr-only">
          {" "}upvotes. Confirmed by {botConfirmations} {botConfirmations === 1 ? "bot" : "bots"}.
        </span>
      </span>
    );
  }
  if (stage === "reported") {
    return (
      <span className="issue-row-status inline-flex items-center gap-1 text-zk-text2">
        <span className="text-amber-400"><BulbIcon /></span> Idea
      </span>
    );
  }
  return <span className="issue-row-status inline-flex items-center gap-1 text-zk-text2">Open</span>;
}
